def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(out),len(out[0])
    # Find rectangular outlines in the non-background color and paint their interiors.
    colors={v for row in out for v in row}
    bg=max(colors, key=lambda x: sum(row.count(x) for row in out))
    for color in colors-{bg}:
